/// <summary>
/// This is an extension class for SysDocuBrandDetails table.
/// </summary>
[ExtensionOf(tableStr(SysDocuBrandDetails))]
final class METSysDocuBrandDetails_Extension
{
}

Method.Source:
/// <summary>
/// Find the unique SysDocuBrandDetails record based on the report name and industry key.
/// </summary>
/// <param name = "_repName">Report name.</param>
/// <param name = "_designName">Design name</param>
/// <param name = "_indKey">Industry key.</param>
/// <param name = "_forUpdate">ForUpdate boolean value.</param>
/// <returns>Returns the SysDocuBrandDetails buffer based on the report name and Industry key.</returns>
public static SysDocuBrandDetails findByRepNameAndIndKey(SrsReportName _repName, SRSReportDesignName _designName, 
                                                         METIndustryKey _indKey, boolean _forUpdate = false)
{
    SysDocuBrandDetails sysDocuBrandDetails;

    if (_repName && _designName && _indKey)
    {
        sysDocuBrandDetails.SelectForUpdate(_forUpdate);

        select firstonly sysDocuBrandDetails 
            where sysDocuBrandDetails.ReportName == _repName
            && sysDocuBrandDetails.DesignName == _designName
            && sysDocuBrandDetails.METIndustryKey == _indKey;
    }

    return sysDocuBrandDetails;
}

/// <summary>
/// Validate the Industry key to be mandatory when report name entered. 
/// </summary>
/// <returns>Return true if validation success, Otherwise false.</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = next validateWrite();

    if ((this.ReportName != this.orig().ReportName || this.METIndustryKey != this.orig().METIndustryKey || this.DesignName != this.orig().DesignName)
        && SysDocuBrandDetails::findByRepNameAndIndKey(this.ReportName, this.DesignName, this.METIndustryKey))
    {
        ret = checkFailed("@MET:ReportNameIndKeyValidation");
    }

    if (!this.METIndustryKey && this.ReportName)
    {
        ret = checkFailed("@MET:IndustryKeMandatory");
    }

    if (!this.DesignName && this.METIndustryKey && this.ReportName)
    {
        ret = checkFailed("@MET:ReportDesignMandatory");
    }

    ret = this.validateTaxRegnum();

    return ret;
}

/// <summary>
/// Validate the ABN to restrict special characters, Allow only numbers and letters.
/// </summary>
/// <returns>Return true if validation success, Otherwise false.</returns>
public boolean validateTaxRegnum()
{
    boolean ret = true;

    TextBuffer txt = new TextBuffer();
    txt.setText(this.METTaxRegNumber);
    txt.regularExpressions(true);

    if (!txt.find(METConstants::sringSpecialChar) && this.METTaxRegNumber != METConstants::emptyString)
    {
        ret = checkFailed("@MET:TaxRegNumValidate");
    }

    return ret;
}
